<?php if ($r['dominios']): ?><div class="gw-card mb-3"><div class="gw-titulo"><span><i class="bi bi-globe2"></i>Domínios cadastrados</span><a href="/dominios">Gerenciar →</a></div><div class="gw-corpo sem-pad table-responsive"><table class="gw-tabela"><tbody>
<?php foreach ($r['dominios'] as $d): ?><tr><td><?= h($d['dominio']) ?></td><td><span class="badge bg-<?= $d['tipo'] === 'whitelist' ? 'success' : 'danger' ?>"><?= h($d['tipo']) ?></span></td></tr><?php endforeach; ?></tbody></table></div></div><?php endif; ?>
